import assert from 'node:assert/strict';import fs from 'node:fs';import * as THREE from 'three';import {Assets} from '../../src/rendering/assets.js';import {assetExpectedBytes} from '../../src/rendering/asset-url.js';import {cropRuntimeDescriptor as descriptor} from '../../src/rendering/crop-runtime.js';
globalThis.document={};globalThis.location={href:'https://itch.io/embed/unrelated-host'};globalThis.self=globalThis;globalThis.ProgressEvent=class {constructor(type,fields){Object.assign(this,{type},fields);}};
const base=new URL('../',process.env.CROP_HOST_MODULE),expected=new URL(descriptor.manifest.slice(1),base),requests=[],assets=new Assets();
globalThis.fetch=async request=>{const url=typeof request==='string'?request:request.url;requests.push(url);assert.ok(url.startsWith(new URL('.',expected).href),url);const file=url.slice(base.href.length),data=fs.readFileSync('public/'+file);assert.equal(assetExpectedBytes(url),data.length);return new Response(data,{headers:{'Content-Length':String(data.length)}});};
assets.textures.loadAsync=async url=>{assert.ok(url.startsWith(new URL('textures/',expected).href));assert.ok(assetExpectedBytes(url)>0);return new THREE.Texture();};
try{const [a,b]=await Promise.all([assets.getCropPartition(),assets.getCropPartition()]);assert.strictEqual(a,b);await a.models('maize');const full=await assets.model(descriptor.collections.steady);let count=0;full.scene.traverse(o=>{if(o.isMesh)count++;});assert.equal(count,40);assert.equal(requests[0],expected.href);assert.equal(requests.length,3);console.log('default collection hosting PASS '+base.href);}finally{assets.disposeModels();}
